\label{11}
A function $f : X \rightarrow Y$ is called $eR$-continuous (briefly $eR$.c.) 
if $f^{-1}(V)$ is $e$-regular in $X$ for every open set $V$ of $Y$.

Let $x \in X$ and $V \in O(Y,f(x))$.\\
$	\left.
	\begin{array}{r}
	(x \in X)(V \in O(Y,f(x))) \\
    f \text{ is $eR$.c.}
	\end{array}
	\right\}\Rightarrow  
	\begin{array}{c}
	\mbox{}\\
	\left.
	\begin{array}{r}
	\!\!\!\! f^{-1}[V] \in eR(X,x)   \\
	U:=f^{-1}[V]
	\end{array}
	\right\} \Rightarrow (U \in eR(X,x))(f[U] \subseteq V \subseteq cl(V)).
	\end{array}
$

\label{q}
From Definitions \ref{2}, \ref{1} and \ref{11}, we have the following diagram. The converses of the below implications are not true in general, as shown in the related articles and following examples.\\
\[
\begin{array}{ccccccccc}
&  & \text{st.}\theta \text{.}s\text{.c.} &  &  &  & BR\text{.c.} & \longrightarrow  & \text{w.$b$.c.}  \\ 
& \nearrow  &  & \searrow  &  &  & \downarrow  &  \nearrow & \uparrow \\ 
\text{st.}\theta \text{.c.} &  &  &  & \text{st.}\theta \text{.}b\text{.c.} & \longrightarrow  & \text{w.}BR\text{.c.} & \longleftarrow  & \text{w.co.} \\ 
& \searrow  &  & \nearrow  &  &  &  & \swarrow  & \downarrow  \\ 
&  & \text{st.}\theta \text{.}p\text{.c.} & \longrightarrow  & \text{st.}\theta \text{.}e\text{.c.} & \longrightarrow  & \text{w.}eR\text{.c.} & \longrightarrow & \text{w.$e$.c.} \\ 
&  &  &  &  &  & \uparrow  & \nearrow  & \uparrow  \\ 
&  &  &  &  &  & eR\text{.c.} & \longrightarrow &  \text{$e$.c.} 
\end{array} 
\]

$(1) \Rightarrow (2):$ Let $x \in X$ and $V \in O(Y,f(x))$.\\
$	\left.
	\begin{array}{r}
	(x \in X)(V \in O(Y,f(x))) \\
    \mbox{ Hypothesis}
	\end{array}
	\right\}\Rightarrow  
	\begin{array}{c}
	\mbox{}\\
	\left.
	\begin{array}{r}
	\!\!\!\! (\exists U \in eR(X,x))(f[U] \subseteq cl(V))   \\
	eR(X) \subseteq e \theta O(X)
	\end{array}
	\right\} \Rightarrow 
	\end{array}
$\\
$\begin{array}{l}
\Rightarrow (\exists U \in e \theta O(X,x))(f[U] \subseteq cl(V)).
\end{array}$
\\

$(2) \Rightarrow (3):$ Let $x \in X \setminus f^{-1}[cl(G)]$ and $G \in PO(Y)$.\\
$
\left.\begin{array}{rr}
x \in X \setminus f^{-1}[cl(G)] \Rightarrow f(x) \in Y \setminus cl(G) \Rightarrow (\exists V \in  O(Y,f(x)))(V \cap G = \emptyset)\\
\mbox{Hypothesis} 
\end{array}\right\} \Rightarrow 
$\\
$\begin{array}{l}
\Rightarrow (\exists U \in e \theta O(X,x))(f[U] \subseteq cl(V))(V \cap G = \emptyset)
\end{array}$\\
$\begin{array}{l}
\Rightarrow (\exists U \in e \theta O(X,x))(f[U] \cap  G = \emptyset)
\end{array}$\\
$\begin{array}{l}
\Rightarrow (\exists U \in e \theta O(X,x))(U \cap  f^{-1}[G] = \emptyset)
\end{array}$\\
$\begin{array}{l}
\Rightarrow x \notin e\mbox{-}cl_\theta(f^{-1}[G])
\end{array}$\\
$\begin{array}{l}
\Rightarrow x \in X \setminus e\mbox{-}cl_\theta(f^{-1}[G]).
\end{array}$\\ 

$(3) \Rightarrow (4):$ Let $G \in PO(Y)$.\\
$
\left.\begin{array}{rr}
G \in PO(Y) \Rightarrow Y \setminus cl(G) \in O(Y) \subseteq PO(Y)\\
\mbox{Hypothesis} 
\end{array}\right\} \Rightarrow  e\mbox{-}cl_\theta ( f^{-1}[Y\setminus cl(G)]) \subseteq f^{-1}[cl(Y\setminus cl(G))]
$\\
$\begin{array}{l}
\Rightarrow X \setminus e\mbox{-}int_\theta ( f^{-1}[cl(G)]) \subseteq X \setminus f^{-1}[int(cl(G))] \subseteq X \setminus f^{-1}[G]
\end{array}$ \\
$\begin{array}{l}
\Rightarrow  f^{-1}[G] \subseteq  e\mbox{-}int_\theta ( f^{-1}[cl(G)]).
\end{array}$ \\ 

$(4) \Rightarrow (5):$ Let $B \subseteq Y$.\\
$
\left.\begin{array}{rr}
B \subseteq Y \Rightarrow Y \setminus cl(B) \in O(Y) \subseteq PO(Y)\\
\mbox{Hypothesis} 
\end{array}\right\} \Rightarrow f^{-1}[Y\setminus cl(B)] \subseteq e\mbox{-}int_\theta ( f^{-1}[cl(Y\setminus cl(B))])
$\\
$\begin{array}{l}
\Rightarrow X \setminus f^{-1}[cl(B)] \subseteq  X \setminus e\mbox{-}cl_\theta ( f^{-1}[int(cl(B))])
\end{array}$ \\
$\begin{array}{l}
\Rightarrow e\mbox{-}cl_\theta ( f^{-1}[int(cl(B))]) \subseteq f^{-1}[cl(B)].
\end{array}$ \\ 

$(5) \Rightarrow (6):$ Let $F \in RC(Y)$.\\
$
\left.\begin{array}{rr}
F \in RC(Y) \Rightarrow int(F) \subseteq Y\\
\mbox{Hypothesis} 
\end{array}\right\} \Rightarrow $\\
$\begin{array}{l}
\Rightarrow e\mbox{-}cl_\theta (f^{-1}[int(F)]) =  e\mbox{-}cl_\theta (f^{-1}[int(cl(int(F)))]) \subseteq f^{-1}[cl(int(F))] = f^{-1}[F].
\end{array}
$\\ 

$(6) \Rightarrow (7):$ Let $U \in O(Y)$.\\
$
\left.\begin{array}{rr}
U \in O(Y) \Rightarrow cl(U) \in RC(Y)\\
\mbox{Hypothesis} 
\end{array}\right\} \Rightarrow e\mbox{-}cl_\theta (f^{-1}[U]) \subseteq  e\mbox{-}cl_\theta (f^{-1}[int(cl(U))]) \subseteq f^{-1}[cl(U)].
$\\ 

$(7) \Rightarrow (8):$ Let $U \in O(Y)$.\\
$
\left.\begin{array}{rr}
U \in O(Y) \Rightarrow Y \setminus cl(U) \in O(Y) \\
\mbox{Hypothesis} 
\end{array}\right\} \Rightarrow e\mbox{-}cl_\theta (f^{-1}[Y \setminus cl(U)]) \subseteq f^{-1}[cl(Y \setminus cl(U))]
$\\
$\begin{array}{l}
\Rightarrow  X \setminus e\mbox{-}int_\theta (f^{-1}[cl(U)]) \subseteq X \setminus f^{-1}[int(cl(U))] \subseteq X \setminus  f^{-1}[U] 
\end{array}$ \\
$\begin{array}{l}
\Rightarrow f^{-1}[U] \subseteq f^{-1}[int(cl(U))] \subseteq e\mbox{-}int_\theta (f^{-1}[cl(U)]).
\end{array}$ \\

$(8) \Rightarrow (9):$ Let $A \subseteq X$.\\
$
\left.\begin{array}{rr}
A \subseteq X \Rightarrow int(Y \setminus f[A]) \in O(Y) \\
\mbox{Hypothesis} 
\end{array}\right\} \Rightarrow  f^{-1}[int(Y \setminus f[A])] \subseteq e\mbox{-}int_\theta (f^{-1}[cl(int(Y \setminus f[A]))])
$\\
$\begin{array}{l}
\Rightarrow  X \setminus f^{-1}[cl(f[A])] \subseteq X \setminus e\mbox{-}cl_\theta (f^{-1}[int(cl(f[A]))])
\end{array}$ \\
$\begin{array}{l}
\Rightarrow  f[e\mbox{-}cl_\theta (f^{-1}[int(cl(f[A]))])]\subseteq f[f^{-1}[cl(f[A])]] 
\end{array}$ \\
$\begin{array}{l}
\Rightarrow  f[e\mbox{-}cl_\theta(A)]\subseteq cl_{\theta }(f[A]).
\end{array}$ \\

$(9) \Rightarrow (10):$ Let $B \subseteq Y$.\\ 
$
\left.\begin{array}{rr}
B \subseteq Y \Rightarrow f^{-1}[B] \subseteq X \\
\mbox{Hypothesis} 
\end{array}\right\} \Rightarrow f[e\mbox{-}cl_\theta (f^{-1}[B])] \subseteq cl_\theta (f[f^{-1}[B]]) \subseteq cl_\theta (B)
$\\
$\begin{array}{l}
\Rightarrow e\mbox{-}cl_\theta (f^{-1}[B]) \subseteq f^{-1}[f[e\mbox{-}cl_\theta (f^{-1}[B])]] \subseteq f^{-1}[cl_\theta (f[f^{-1}[B]])] \subseteq f^{-1}[cl_\theta (B)].
\end{array}$ \\ 

$(10) \Rightarrow (11):$ Let $B \subseteq Y$.\\
$
\left.\begin{array}{rr}
B \subseteq Y \Rightarrow int(cl_\theta (B)) \subseteq Y \\
\mbox{Hypothesis} 
\end{array}\right\} \Rightarrow e\mbox{-}cl_\theta (f^{-1}[int(cl_\theta (B))]) \subseteq f^{-1}[cl_\theta (int(cl_\theta (B)))] \subseteq f^{-1}[cl_\theta (B)].
$\\ 

$(11) \Rightarrow (1):$ Let $x \in X$ and $U \in O(Y,f(x))$.\\
$	\left.
	\begin{array}{r}
	(x \in X)(U \in O(Y,f(x))) \\
    \mbox{ Hypothesis}
	\end{array}
	\right\}\Rightarrow  
	\begin{array}{c}
	\mbox{}\\
	\left.
	\begin{array}{r}
	\!\!\!\!\! e\mbox{-}cl_\theta (f^{-1}[int(cl_\theta (U))]) \subseteq  f^{-1}[cl_\theta (U)]\\
	U \subseteq int(cl(U))=int(cl_\theta(U))
	\end{array}
	\right\} \Rightarrow 
	\end{array}
$\\
$\begin{array}{l}
\Rightarrow e\mbox{-}cl_\theta (f^{-1}[U]) \subseteq e\mbox{-}cl_\theta (f^{-1}[int(cl_\theta (U))]) \subseteq f^{-1}[cl_\theta (U)]  \overset{\text{Lemma \ref{bsa}} }{=} f^{-1}[cl(U)]
\end{array}$ \\

It follows by $(1) \Leftrightarrow (7)$ that $f$ is weakly $eR$ continuous.

Let $H \in aO(X,x)$ ve $V \in O(Y,f(x))$.\\
$
\left.\begin{array}{rr}
(H \in aO(X,x))(V \in O(Y,f(x)))\\
f \mbox{ is w.$eR$.c. at $x \in X$}
\end{array}\right\} \overset{\text{Theorem } \ref{4}}{\Rightarrow } x \in e\mbox{-}int_{\theta}(f^{-1}[cl(V)])
$\\
$
\left.\begin{array}{rr}
 \overset{\text{Lemma } \ref{*}(9)}{\Rightarrow} (\exists G \in eR(X,x))(G \subseteq e\mbox{-}int_{\theta}(f^{-1}[cl(V)]))\\
U:=G \cap H 
\end{array}\right\} \overset{\text{Lemma } \ref{5}}{\Rightarrow } 
$\\
$\begin{array}{l}
\Rightarrow   (U \in eO(X,x))(U \subseteq H)(U \subseteq G \subseteq e\mbox{-}int_{\theta }(f^{-1}[cl(V)]) \subseteq e\mbox{-}cl_{\theta }(f^{-1}[cl(V)])).
\end{array}$

$(1) \Rightarrow (2):$ Let $x \in X$ and $V \in O(Y,f(x))$.\\
$	\left.
	\begin{array}{r}
	(x \in X)(V \in O(Y,f(x))) \\
    Y \mbox{ is regular}
	\end{array}
	\right\}\Rightarrow  
	\begin{array}{c}
	\mbox{}\\
	\left.
	\begin{array}{r}
	\!\!\!\! (\exists H \in O(Y,f(x)))(cl(H) \subseteq V)   \\
	f \mbox{ is w.$eR$.c.}
	\end{array}
	\right\} \Rightarrow 
	\end{array}$\\
$\begin{array}{l}
\Rightarrow (\exists U \in eR(X,x))(f[U] \subseteq cl(H) \subseteq V)
\end{array}$\\ 
Then by Theorem \ref{6} $f$ is strongly $\theta$-$e$-continuous.\\ 

$(2) \Rightarrow (1):$ It is obvious from Definitions \ref{2} and \ref{1}.

Suppose that $Y$ is not connected.\\
$\left. 
	\begin{array}{c}
	Y\mbox{ is not connected}\Rightarrow (\exists A,B\in O(Y) \setminus
	\{\emptyset\} )(A\cap B=\emptyset )(A\cup B=Y)
	\end{array}
	\right. $\newline
	$\left. 
	\begin{array}{r}
	\Rightarrow (A,B\in CO(Y)\setminus \{\emptyset \})(A\cap B=\emptyset )(A\cup
	B=Y) \\ 
	f\mbox{ is w.$eR$.c.}
	\end{array}
	\right\} \overset{\text{Theorem \ref{3}(8)}}{\Rightarrow } $\newline
	$
	\begin{array}{r}
	\Rightarrow f^{-1}[A]\subseteq e\mbox{-}int_\theta(f^{-1}[cl(A)])=e\mbox{-}int_\theta(f^{-1}[A])
	\end{array}$\\
	$\left. 
	\begin{array}{r}
	\! \Rightarrow (f^{-1}[B]\subseteq e\mbox{-}int_\theta(f^{-1}[cl(B)])=e\mbox{-}int_\theta(f^{-1}[B]))(f^{-1}[A\cap	B]=\emptyset )(f^{-1}[A\cup B]=X) \\ 
	f\mbox{ is surjection}
	\end{array}
	\right\} \Rightarrow $\newline
	$\left. 
	\begin{array}{c}
	\Rightarrow (f^{-1}[A],f^{-1}[B]\in eO(X)\setminus \{\emptyset
	\})(f^{-1}[A]\cap f^{-1}[B] =\emptyset )(f^{-1}[A]\cup
	f^{-1}[B] =X)
	\end{array}
	\right. $ \\

 This is a contradiction to the fact that $X$ is $e$-connected. Thus, $Y$ is connected.

Let $x \notin A $.\\
        $\left. 
	\begin{array}{r}
	x \notin A  \Rightarrow f(x) \neq g(x)\\ 
	Y \text{ is Urysohn}
	\end{array}
	\right\} \Rightarrow $\\
$\left. 
	\begin{array}{r}
	\Rightarrow (\exists V_1 \in O(Y,f(x)))(\exists V_2 \in O(Y,g(x)))(cl(V_1) \cap cl(V_2)=\emptyset) \\ 
	(f \text { is w.$eR$.c.})(g \text { is w.$a$.c.})
	\end{array}
	\right\} \Rightarrow  $\\
$
\left.\begin{array}{rr}
 \Rightarrow (\exists U \in eR(X,x))(\exists G \in aO(X,x))(f[U] \subseteq cl(V_1))(g[G] \subseteq cl(V_2))\\
W:=U \cap G 
\end{array}\right\} \overset{\text{Lemma } \ref{5}}{\Rightarrow} $\\
$\begin{array}{l}
\Rightarrow (\exists W \in eO(X,x))(f[W] \cap g[W] \subseteq f[U] \cap g[G] \subseteq cl(V_1) \cap cl(V_2)=\emptyset)
\end{array}$\\
$\begin{array}{l}
\Rightarrow (\exists W \in eO(X,x))(W \cap A=\emptyset)
\end{array}$\\
$\begin{array}{l}
\Rightarrow x \notin e\text{-}cl(A).
\end{array}$

Let $x,y \in X$ and $x \neq y$.\\
$\left. 
\begin{array}{r}
(x,y \in X)(x \neq y) \overset{f\text{ is injective}}{\Rightarrow} f(x) \neq f(y)\\ 
Y \mbox{ is Hausdorff}
\end{array}
\right\} \Rightarrow  (\exists U \in O(Y,f(x))(\exists V \in O(Y,f(y))(U \cap V=\emptyset)$\\
$\left. 
\begin{array}{r}
\Rightarrow (\exists U \in O(Y,f(x))(\exists V \in O(Y,f(y))(f(x) \notin cl(V))(f(y) \notin cl(U))\\ 
f \mbox{ is w.$eR$.c.}
\end{array}
\right\} \Rightarrow $\\	
$\begin{array}{l}
\Rightarrow (\exists A \in eR(X,x))(\exists B \in eR(X,y))(f[A] \subseteq  cl(U))(f[B] \subseteq  cl(V))
\end{array}$\\
$\begin{array}{l}
\Rightarrow (\exists A \in eR(X,x))(\exists B \in eR(X,y))(y \notin A)(x \notin B).
\end{array}$

Let $x,y \in X$ and $x \neq y$.\\
$\left. 
\begin{array}{r}
(x,y \in X)(x \neq y) \overset{f\text{ is injective}}{\Rightarrow} f(x) \neq f(y)\\ 
Y \mbox{ is Urysohn}
\end{array}
\right\} \Rightarrow $\\
$\left. 
\begin{array}{r}
\Rightarrow (\exists U \in O(Y,f(x))(\exists V \in O(Y,f(y))(cl(U) \cap cl(V)=\emptyset) \\ 
f \mbox { is w.$eR$.c.}
\end{array}
\right\} \Rightarrow $\\
$\begin{array}{l}
\Rightarrow (\exists A \in eR(X,x))(\exists B \in eR(X,y))(f[A] \subseteq  cl(U))(f[B] \subseteq  cl(V))
\end{array}$\\
$\begin{array}{l}
\Rightarrow (\exists A \in eR(X,x))(\exists B \in eR(X,y))(A \subseteq  f^{-1}[cl(U)])(B \subseteq  f^{-1}[cl(V)])
\end{array}$\\
$\begin{array}{l}
\Rightarrow (\exists A \in eR(X,x))(\exists B \in eR(X,y))(A \cap B \subseteq  f^{-1}[cl(U)] \cap f^{-1}[cl(V)]=\emptyset).
\end{array}$

Let $x=\{x_{\alpha }\}\in \Pi X_{\alpha }$ and $V\in O(\Pi Y_{\alpha },f(x))$.\\
        $\begin{array}{l}
        V\in O(\Pi Y_{\alpha },f(x))\Rightarrow (\exists J=\{\alpha _{1},\alpha	_{2},\ldots ,\alpha _{n}\}\subseteq I)
        \end{array}$\\
        $\left. 
	\begin{array}{r}
	\left( W_{\alpha }:=\left\{ 
	\begin{array}{ccc}
	W_{\alpha _{j}}\in O(Y_{\alpha _{j}}) & , & \alpha \in J \\ 
	Y_{\alpha } & , & \alpha \notin J 
	\end{array}
	\right. \right)\left( 
	\Pi W_{\alpha }\in O(\Pi Y_{\alpha },f(x))\right) \left( \newline
	\Pi W_{\alpha }\subseteq V\right)  \\ 
	(\forall \alpha \in I)(f_{\alpha }\mbox{ is w.$eR$.c.})
	\end{array}
	\right\} \Rightarrow $\newline
	$\left. 
	\begin{array}{r}
	\Rightarrow (\exists U_{\alpha }\in eR(X_{\alpha },x_{\alpha
	}))\left( f_{\alpha }[U_{\alpha }]\subseteq cl(W_{\alpha })\right)  \\ 
	U:=\prod\limits_{j=1}^{n}U_{\alpha _{j}}\times \prod\limits_{\alpha \notin
		J}X_{\alpha }
	\end{array}
	\right\}  \Rightarrow  $\\
	$\left. 
	\begin{array}{c}
	\Rightarrow (U\in eR(\Pi X_{\alpha },x))\left( f[U]\subseteq
	\prod\limits_{j=1}^{n}f_{\alpha }[ U_{\alpha _{j}}] \times
	\prod\limits_{\alpha \notin J}Y_{\alpha }\subseteq
	\prod\limits_{j=1}^{n}cl( W_{\alpha _{j}}) \times
	\prod\limits_{\alpha \notin J}Y_{\alpha }\subseteq cl(V)\right).
	\end{array}
	\right. $

Let $(x,y) \notin G(f).$\\
$
\left.\begin{array}{rr}
(x,y) \notin G(f) \Rightarrow y \neq f(x)\\
Y \mbox{ is Urysohn}
\end{array}\right\} \Rightarrow 
$\\
$
\left.\begin{array}{rr}
\Rightarrow (\exists A\in O(X,f(x)))(\exists B\in O(Y,y))(cl(A) \cap cl(B)=\emptyset )\\
f\mbox{ is w.$eR$.c.}
\end{array}\right\} \Rightarrow 
$\\
 $\begin{array}{c}
\Rightarrow (\exists G\in eR(X,x))(\exists B\in O(Y,y))(f[G]\subseteq cl(A))
\end{array} $\\
$\begin{array}{c}
\Rightarrow (\exists G\in eR(X,x))(\exists B\in O(Y,y))(f[G] \cap cl(B)= \emptyset)
\end{array}$\\
$\begin{array}{c}
\Rightarrow (\exists G\in eR(X,x))(\exists B\in O(Y,y))((G\times cl(B))\cap G(f)=\emptyset).
\end{array}$

Let $x,y \in X$ and $x \neq y$.\\
$
\left.\begin{array}{rr}
(x,y \in X)(x \neq y)  \overset{f \text{ is injective}}{\Rightarrow} f(x) \neq f(y)  \Rightarrow  (x,f(y)) \notin G(f) \\
G(f) \mbox{ is $er$-graph}
\end{array}\right\} \Rightarrow $\\
$\begin{array}{l}
\Rightarrow (\exists U\in eR(X,x))(\exists V\in O(Y,f(y)))( (U\times cl(V))\cap G(f)=\emptyset) 
\end{array}$\\
$
\left.\begin{array}{rr}
\Rightarrow (\exists U\in eR(X,x))(\exists V\in O(Y,f(y)))( f[U]\cap cl(V)=\emptyset)   \\
f \mbox{ is w.$eR$.c.}
\end{array}\right\} \Rightarrow $\\
 $\begin{array}{c}
\Rightarrow (\exists U\in eR(X,x))(\exists W\in eR(X,y))(f[W]\subseteq cl(V))
\end{array} $\\
$\begin{array}{c}
\Rightarrow (\exists U\in eR(X,x))(\exists W\in eR(X,y))(f[U]\cap f[W] = \emptyset)
\end{array}$\\
$\begin{array}{c}
\Rightarrow (\exists U\in eR(X,x))(\exists W\in eR(X,y))(U \cap V = \emptyset).
\end{array}$

Let $K$ be $eR$-compact relative to $X$ and $y\notin f[K].$ \newline
$\left.
\begin{array}{r}
y\notin f[K]\Rightarrow (\forall x\in K)(\left( x,y\right) \notin G(f)) \\
G(f) \mbox{ is $er$-graph}
\end{array} 
\right\} \overset{\text{Lemma \ref{10}}}{\Rightarrow} $\newline
$\begin{array}{c}
\Rightarrow (\exists U_{x}\in eR(X,x))(\exists V_{x}\in O(Y,y))(f[U_{x}]\cap cl( V_{x})=\emptyset )
\end{array}$\\
$\left.
\begin{array}{r}
\Rightarrow (\{U_{x}|x\in K\}\subseteq eR(X))(K\subseteq \bigcup \{U_{x}|x\in K\}) 
\\
K\mbox{ is }eR\mbox{-compact relative to }X 
\end{array} 
\right\} \Rightarrow $\newline
$\left.
\begin{array}{r}
\Rightarrow (\exists K^{\ast }\subseteq K)(|K^{\ast }|<\aleph_{0})\newline
(K\subseteq \bigcup \{U_{x}|x\in K^{\ast }\}) \\
V:=\underset{x\in K^{\ast }}{\bigcap}V_{x}\in O(Y,y) 
\end{array} 
\right\} \Rightarrow $\newline
$\left.
\begin{array}{c}
\Rightarrow \left( V\in O(Y,y)\right) \left( f[K]\cap V\subseteq \left(
\underset{x\in K^{\ast }}{\bigcup }f\left[U_{x}\right]  \right) 
\cap cl(V) \subseteq 
\underset{x\in K^{\ast }}{\bigcup}\left(f\left[U_{x}\right]   
\cap cl(V) \right)=\emptyset \right) \newline
\end{array} 
\newline
\right. $\newline
$\left.
\begin{array}{c}
\Rightarrow y\notin cl_{\theta }(f[K]).\newline
\end{array} 
\newline
\right. $
